# Generated by forge. pytest's filterwarnings turns a framework's next-version
# deprecations into errors (run by .forge/check.sh with the project's own Python,
# 3.11+). Usage:
#   python pytest_filterwarnings.py <forge-tmp> <entry> <dependency>
# Reads the pytest configuration pytest itself uses (the first of pytest.ini,
# .pytest.ini, pyproject.toml with [tool.pytest] or [tool.pytest.ini_options],
# tox.ini with [pytest], setup.cfg with [tool:pytest]) and prints a finding when its
# filterwarnings has neither <entry> nor a bare "error".
# Exit 0: nothing found; 1: finding printed ("path:0 message"); 3: cannot run.
import configparser
import os
import sys

try:
    import tomllib
except ImportError:
    print("skipped: tomllib needs Python 3.11+")
    sys.exit(3)


def ini(path, section):
    p = configparser.ConfigParser(interpolation=None)
    try:
        p.read(path, encoding="utf-8")
    except configparser.Error:
        return None
    if not p.has_section(section):
        return None
    return [l.strip() for l in p[section].get("filterwarnings", "").splitlines() if l.strip()]


def toml(path):
    try:
        with open(path, "rb") as f:
            tool = tomllib.load(f).get("tool") or {}
    except (OSError, tomllib.TOMLDecodeError):
        return None
    pytest = tool.get("pytest")
    if not isinstance(pytest, dict):
        return None
    # pytest 9 reads [tool.pytest] itself, older versions [tool.pytest.ini_options]
    opts = pytest if "ini_options" not in pytest else pytest["ini_options"]
    v = opts.get("filterwarnings", [])
    return [str(x).strip() for x in (v if isinstance(v, list) else str(v).splitlines()) if str(x).strip()]


def config():
    for path, read in (("pytest.ini", lambda p: ini(p, "pytest") or []), (".pytest.ini", lambda p: ini(p, "pytest") or []),
                       ("pyproject.toml", toml), ("tox.ini", lambda p: ini(p, "pytest")), ("setup.cfg", lambda p: ini(p, "tool:pytest"))):
        if os.path.isfile(path):
            entries = read(path)
            if entries is not None:
                return path, entries
    return "pyproject.toml", []


def main():
    entry, dep = sys.argv[2], sys.argv[3]
    path, entries = config()
    norm = {e.replace(" ", "") for e in entries}
    if entry.replace(" ", "") in norm or "error" in norm:
        return 0
    print(f'{path}:0 pytest filterwarnings has no "{entry}": {dep} deprecations only warn, so tests pass on code the next {dep} release breaks; add it')
    return 1


try:
    sys.exit(main())
except SystemExit:
    raise
except Exception as e:  # never report a crash as a finding
    print(f"skipped: pytest_filterwarnings.py could not run ({type(e).__name__}: {e})")
    sys.exit(3)
